    }

    if (stressCpu)
    {
        for (int k = 0; k < cpuScansPerFrame; k++)
        {
            var allObjects = GameObject.FindObjectsOfType<GameObject>();
            GC.KeepAlive(allObjects);
        }
    }

    if (stressDraw && testPrefab != null)
    {
        int n = Mathf.Max(1, cubesPerFrame);
        for (int i = 0; i < n; i++) SpawnOne();
    }
}",
      "explicacao_didatica": "O Garbage Collector (GC) e o mecanismo automatico responsavel por liberar a memoria que o jogo nao esta mais usando. Quando o codigo cria novos textos ou colecoes dentro do Update (que roda dezenas de vezes por segundo), a memoria gerenciada se esgota rapidamente. Quando isso acontece, o jogo congela para que o GC realize a limpeza, gerando picos de travamento (stuttering). Para manter a taxa de quadros estavel, evite alocar novos objetos e concatenar textos dentro de rotinas frequentes."
    }
  ],
